package com.gregtech.gregtech.content.plant;
public final class BaleAgingRules {private BaleAgingRules(){}public static boolean canAge(String stage){return stage.equals("FRESH")||stage.equals("MOLDY");}public static int initialDelay(int random2400){return 2400+random2400;}public static int retryDelay(int random200){return 1100+random200;}public static String freshResult(boolean wet){return wet?"MOLDY":"DRY";}public static String id(String stage){return switch(stage){case "DRY"->"bale_grass_dry";case "MOLDY"->"bale_grass_moldy";case "ROTTEN"->"bale_grass_rotten";default->throw new IllegalArgumentException("Not an ageing result: "+stage);};}}
